    async def get_database_measurements(
        self,
        group_id: str,
        process_id: str,
        database_name: str,
        *,
        granularity: str,
        m: typing.Optional[typing.Union[str, typing.Sequence[str]]] = None,
        period: typing.Optional[str] = None,
        start: typing.Optional[dt.datetime] = None,
        end: typing.Optional[dt.datetime] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ApiMeasurementsGeneralViewAtlas:
        """
        Returns the measurements of one database for the specified host for the specified project. Returns the database's on-disk storage space based on the MongoDB `dbStats` command output. To calculate some metric series, Atlas takes the rate between every two adjacent points. For these metric series, the first data point has a null value because Atlas can't calculate a rate for the first data point given the query time range. Atlas retrieves database metrics every 20 minutes but reduces frequency when necessary to optimize database performance. To use this resource, the requesting Service Account or API Key must have the Project Read Only role.

        Parameters
        ----------
        group_id : str
            Unique 24-hexadecimal digit string that identifies your project. Use the [/groups](#tag/Projects/operation/listProjects) endpoint to retrieve all projects to which the authenticated user has access.

            **NOTE**: Groups and projects are synonymous terms. Your group id is the same as your project id. For existing groups, your group/project id remains the same. The resource and corresponding endpoints use the term groups.

        process_id : str
            Combination of hostname and Internet Assigned Numbers Authority (IANA) port that serves the MongoDB process. The host must be the hostname, fully qualified domain name (FQDN), or Internet Protocol address (IPv4 or IPv6) of the host that runs the MongoDB process (`mongod` or `mongos`). The port must be the IANA port on which the MongoDB process listens for requests.

        database_name : str
            Human-readable label that identifies the database that the specified MongoDB process serves.

        granularity : str
            Duration that specifies the interval at which Atlas reports the metrics. This parameter expresses its value in the ISO 8601 duration format in UTC.

        m : typing.Optional[typing.Union[str, typing.Sequence[str]]]
            One or more types of measurement to request for this MongoDB process. If omitted, the resource returns all measurements. To specify multiple values for `m`, repeat the `m` parameter for each value. Specify measurements that apply to the specified host. MongoDB Cloud returns an error if you specified any invalid measurements.

        period : typing.Optional[str]
            Duration over which Atlas reports the metrics. This parameter expresses its value in the ISO 8601 duration format in UTC. Include this parameter when you do not set **start** and **end**.

        start : typing.Optional[dt.datetime]
            Date and time when MongoDB Cloud begins reporting the metrics. This parameter expresses its value in the ISO 8601 timestamp format in UTC. Include this parameter when you do not set **period**.

        end : typing.Optional[dt.datetime]
            Date and time when MongoDB Cloud stops reporting the metrics. This parameter expresses its value in the ISO 8601 timestamp format in UTC. Include this parameter when you do not set **period**.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ApiMeasurementsGeneralViewAtlas
            OK

        Examples
        --------
        import asyncio

        from atlas_sdk import AsyncAtlasClient

        client = AsyncAtlasClient(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.monitoring_and_logs.get_database_measurements(
                group_id="32b6e34b3d91647abb20e7b8",
                process_id="mongodb.example.com:27017",
                database_name="databaseName",
                granularity="PT1M",
                period="PT10H",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.get_database_measurements(
            group_id,
            process_id,
            database_name,
            granularity=granularity,
            m=m,
            period=period,
            start=start,
            end=end,
            request_options=request_options,
        )
        return _response.data

